新增 infra/reconstruction/paired_width_delta.py，作为 restore_luminaire_glb.py 的 transplant() 输出经相同相机渲染后的离线验收，不改材质来迁就阈值。依赖 Python 3、NumPy。photo 是独立人工标注的完整分辨率整数标签：0=确定背景，1=确定杆体，2=填补阴影/阴影边界不确定，3=缺段或未标注，4=遮挡；确定属于杆体的暗部仍标 1。old/new 是各自隔离渲染的同一稳定对象 ID 图，visible 是对应完整场景的可见 ID 图。必须使用相同相机、分辨率、像素坐标和 ID 语义，不允许裁剪缩放。centre 是共同物理截面投影中心，tangent 是共同轴线上固定两点的投影差，而非分别拟合版本外观。以下代码可保存后直接运行：

```python
def paired_width_delta(photo, old, new, visible, centre, tangent, oid=1):
    import numpy as np
    photo, old, new, vo, vn = [np.asarray(a) for a in (photo, old, new, *visible)]
    arrays = (photo, old, new, vo, vn)
    if any(a.ndim != 2 or a.shape != photo.shape or a.dtype.kind not in 'iu' for a in arrays):
        raise ValueError('integer_registered_labels_required')
    if oid <= 0 or not np.isin(photo, [0, 1, 2, 3, 4]).all(): raise ValueError('labels')
    c, t = np.asarray(centre, float), np.asarray(tangent, float)
    if c.shape != (2,) or t.shape != (2,) or not np.isfinite([c, t]).all(): raise ValueError('coordinates')
    length = np.linalg.norm(t)
    if length < 1: raise ValueError('projected_axis')
    t = t / length; normal = np.array([-t[1], t[0]])
    s = np.arange(-16., 16.001, .25); ray = c + s[:, None] * normal
    band = np.stack((ray - t, ray, ray + t))
    def sample(a, points):
        a = np.asarray(a, float); x, y = points[..., 0], points[..., 1]
        if ((x < 0) | (y < 0) | (x >= a.shape[1]-1) | (y >= a.shape[0]-1)).any():
            raise ValueError('image_boundary')
        ix, iy = np.floor(x).astype(int), np.floor(y).astype(int)
        u, v = x - ix, y - iy
        return ((1-u)*(1-v)*a[iy, ix] + u*(1-v)*a[iy, ix+1]
                + (1-u)*v*a[iy+1, ix] + u*v*a[iy+1, ix+1])
    for code, reason in ((2, 'filled_shadow'), (3, 'missing_segment'), (4, 'photo_occlusion')):
        if (sample(photo == code, band) > 0).any(): raise ValueError(reason)
    for isolated, seen in ((old, vo), (new, vn)):
        if (sample((isolated == oid) != (seen == oid), band) > 0).any(): raise ValueError('render_occlusion')
    widths, positions = [], []
    for mask in (photo == 1, old == oid, new == oid):
        values = sample(mask, ray)
        k = np.flatnonzero((values[:-1] >= .5) != (values[1:] >= .5))
        if len(k) != 2 or values[0] >= .5 or values[-1] >= .5 or sample(mask, c[None])[0] < .5:
            raise ValueError('clipped_split_or_missing_edges')
        edges = s[k] + .25 * (.5-values[k]) / (values[k+1]-values[k])
        points = c + edges[:, None] * normal
        gx = sample(mask, points + [.5, 0]) - sample(mask, points - [.5, 0])
        gy = sample(mask, points + [0, .5]) - sample(mask, points - [0, .5])
        gradient = np.stack((gx, gy), axis=1); strength = np.linalg.norm(gradient, axis=1)
        if (strength < .25).any() or (abs(gradient @ normal) < .7 * strength).any():
            raise ValueError('ill_conditioned_edges')
        widths.append(float(edges[1]-edges[0])); positions.append(points.tolist())
    p, o, n = widths
    return {'photo': p, 'old': o, 'new': n, 'delta': abs(o-p)-abs(n-p), 'edges_xy': positions}

if __name__ == '__main__':
    import numpy as np
    p = np.zeros((32, 48), np.uint8); p[:, 21:28] = 1
    o = np.zeros_like(p); o[:, 19:29] = 1
    n = np.zeros_like(p); n[:, 20:28] = 1
    result = paired_width_delta(p, o, n, (o, n), (24, 16), (0, 4))
    assert np.allclose([result[k] for k in ('photo', 'old', 'new', 'delta')], [7, 10, 8, 2])
    shadow = p.copy(); shadow[:, 24] = 2
    missing = p.copy(); missing[:, 24] = 3
    occluded = o.copy(); occluded[:, 19] = 0
    for target, vis, axis, reason in ((shadow, (o,n), (0,4), 'filled_shadow'), (missing, (o,n), (0,4), 'missing_segment'), (p, (occluded,n), (0,4), 'render_occlusion'), (p, (o,n), (0,0), 'projected_axis')):
        try: paired_width_delta(target, o, n, vis, (24,16), axis)
        except ValueError as exc: assert str(exc) == reason
        else: raise AssertionError(reason)
```

这里的 0.5 是二值标签覆盖率的边界约定，不是旧版或新版颜色阈值。双线性插值只定义标签栅格上的边缘位置，不声称获得了照片真实亚像素精度。
